// Picks files that should be retried:
//  - Status = failed  (transient error, attempts left)
//  - Status = processing but stale (> 2h) -> the run crashed midway
const STALE_MS = 2 * 60 * 60 * 1000;
const now = Date.now();
return $input.all()
  .map(i => i.json)
  .filter(r => r['File ID'] && (
    r.Status === 'failed' ||
    (r.Status === 'processing' && now - Date.parse(r['Updated At']) > STALE_MS)
  ))
  .map(r => ({ json: { id: r['File ID'], name: r['File Name'], fromRetry: true } }));

// ===== CONFIG: everything you may want to tune lives here =====
const CONFIG = {
  maxAttempts: 3,                 // total tries per file (incl. scheduled retries)
  maxFileSizeMB: 25,              // Groq Whisper upload limit for your plan
  directThreshold: 15000,         // chars; above this -> map-reduce
  chunkSize: 6000,                // chars per chunk (map step)
  chunkOverlap: 300,              // chars repeated between chunks
  minTranscriptChars: 20,         // shorter = treated as empty/silent audio
  summaryLanguage: 'English',     // or: 'the same language as the transcript'
  summariesFolderId: '',          // Drive folder ID for summary docs (empty = My Drive root)
  n8nBaseUrl: '',                 // e.g. 'https://n8n.example.com' -> adds "Open execution" link to alerts
};
// ===============================================================

const f = $input.first().json;
const fileId = f.id || f.fileId;
const fileName = f.name || f.fileName || fileId;
const mimeType = f.mimeType || '';
const sizeMB = f.size ? Number(f.size) / 1048576 : null;
const SUPPORTED_EXT = ['flac', 'mp3', 'mp4', 'mpeg', 'mpga', 'm4a', 'ogg', 'opus', 'wav', 'webm'];
const ext = String(fileName || '').split('.').pop().toLowerCase();

let reason = '';
if (!fileId) {
  reason = 'Missing file ID';
} else if (mimeType && !mimeType.startsWith('audio/') && !mimeType.startsWith('video/') && !SUPPORTED_EXT.includes(ext)) {
  reason = `Unsupported file type (${mimeType}). Supported: ${SUPPORTED_EXT.join(', ')}`;
} else if (sizeMB !== null && sizeMB > CONFIG.maxFileSizeMB) {
  reason = `File is ${sizeMB.toFixed(1)} MB, limit is ${CONFIG.maxFileSizeMB} MB. Compress it (e.g. mono 64 kbps mp3) and re-upload.`;
}

return [{ json: { fileId, fileName, mimeType, sizeMB, valid: !reason, reason, config: CONFIG } }];

const file = $('Validate File').first().json;
const row = $input.first()?.json || {};
const status = String(row.Status || '').trim();
const prevAttempts = Number(row.Attempts) || 0;
let attempts = prevAttempts + 1;
const STALE_MS = 2 * 60 * 60 * 1000;
const stale = status === 'processing' && Date.now() - Date.parse(row['Updated At']) > STALE_MS;

let action = 'process';
let reason = file.reason;
if (status === 'done' || status === 'failed_permanent' || (status === 'processing' && !stale)) action = 'skip';
else if (!file.valid) action = 'reject';
else if (attempts > file.config.maxAttempts) {
  // e.g. the run keeps crashing (out of memory) and never reaches Build Error
  action = 'reject';
  attempts = prevAttempts;   // nothing new was tried -> alert shows 3/3, not 4/3
  reason = `Gave up after ${prevAttempts} attempts (previous runs crashed or kept failing)`;
}

return [{ json: { ...file, reason, previousStatus: status || 'new', attempts, action } }];

const cfg = $('Validate File').first().json.config;
const r = $input.first().json;
const transcript = String(r.text || '').trim();

// "PERMANENT:" prefix tells Build Error not to retry this file
if (transcript.length < cfg.minTranscriptChars) {
  throw new Error('PERMANENT: Transcript is empty or too short (silent / non-speech audio?)');
}

return [{ json: {
  transcript,
  length: transcript.length,
  language: r.language || 'unknown',          // auto-detected by Whisper (english, turkish, ...)
  durationMin: Math.round((r.duration || 0) / 60),
} }];

const cfg = $('Validate File').first().json.config;
const text = $input.first().json.transcript;
const size = cfg.chunkSize, overlap = cfg.chunkOverlap;

// Split on sentence boundaries so no sentence is cut in half
const sentences = text.match(/[^.!?…]+[.!?…]+["')\]]*\s*|[^.!?…]+$/g) || [text];
const chunks = [];
let cur = '';
for (const s of sentences) {
  if (cur.length + s.length > size && cur.length > 0) {
    chunks.push(cur.trim());
    cur = cur.slice(-overlap) + s;   // keep some context from the previous chunk
  } else {
    cur += s;
  }
}
if (cur.trim()) chunks.push(cur.trim());

// Safety net: hard-split anything still too long (e.g. no punctuation at all)
const out = [];
for (const c of chunks) for (let i = 0; i < c.length; i += size) out.push(c.slice(i, i + size));

return out.map((chunk, i) => ({ json: { chunk, index: i + 1, total: out.length } }));

// Never send a partial summary: if any chunk failed, fail the whole file.
const items = $input.all();
const expected = $('Split Transcript Into Chunks').all().length;
const failed = items.filter(i => i.json.error || !String(i.json.text || '').trim());

if (items.length !== expected || failed.length) {
  const e = failed[0]?.json.error;
  const detail = typeof e === 'string' ? e : (e?.message || 'missing output');
  throw new Error(`${failed.length || expected - items.length} of ${expected} chunk summaries failed: ${detail}`);
}

return [{ json: {
  combinedSummaries: items.map((i, n) => `### Part ${n + 1}\n${i.json.text}`).join('\n\n'),
} }];

const raw = String($input.first().json.text || '').trim();
if (raw.length < 20) throw new Error('LLM returned an empty or too short summary');

const file = $('Decide Action').first().json;
const t = $('Prepare Transcript').first().json;

// First line is "Topic: ..." -> pull it out as the message title
const m = raw.match(/^\s*\**\s*(?:topic|konu)\s*:?\s*\**\s*:?\s*(.+)\n/i);
const fallback = String(file.fileName).replace(/\.[^.]+$/, '');
const topic = (m ? m[1] : fallback).replace(/[*_]/g, '').trim().slice(0, 120) || fallback;
const summary = (m ? raw.slice(m[0].length) : raw).trim();

const lang = String(t.language || 'unknown');
const languageLabel = lang.charAt(0).toUpperCase() + lang.slice(1);
const durationLabel = t.durationMin < 1 ? '< 1 min' : `${t.durationMin} min`;

return [{ json: {
  topic,
  summary,
  fileId: file.fileId,
  fileName: file.fileName,
  attempts: file.attempts,
  language: t.language,
  languageLabel,
  durationMin: t.durationMin,
  durationLabel,
} }];

// Builds a Drive multipart upload: plain text in, Google Doc out.
// Drive converts it itself, so only the Drive API is needed (no Google Docs API).
const cfg = $('Validate File').first().json.config;
const s = $input.first().json;
const t = $('Prepare Transcript').first().json;
const now = new Date().toISOString().slice(0, 16).replace('T', ' ');

const content = [
  s.topic,
  '',
  `File: ${s.fileName}`,
  `Processed: ${now} (UTC)`,
  `Detected language: ${s.language}`,
  `Duration: ~${s.durationMin} min`,
  '',
  '===== SUMMARY =====',
  '',
  s.summary.replace(/\*/g, ''),          // strip Slack bold markers for the doc
  '',
  '===== FULL TRANSCRIPT =====',
  '',
  t.transcript,
].join('\n');

const metadata = {
  name: `${now.slice(0, 10)} - ${s.topic}`,
  mimeType: 'application/vnd.google-apps.document',
};
if (cfg.summariesFolderId) metadata.parents = [cfg.summariesFolderId];

const B = 'meeting_summary_boundary';
const body =
  `--${B}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n` +
  `--${B}\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n${content}\r\n` +
  `--${B}--`;

return [{ json: { body, contentLength: content.length } }];

// Single error collector for every stage.
const ctx = $('Decide Action').first().json;
const cfg = ctx.config;
const stage = $prevNode.name;
const raw = $input.first()?.json || {};

let message;
if (stage === 'Route by Action') {
  message = 'PERMANENT: ' + ctx.reason;              // failed validation
} else {
  const e = raw.error;
  message = (typeof e === 'string' ? e : (e?.message || e?.description)) || raw.message || 'Unknown error';
  if (e?.description && e?.message && !message.includes(e.description)) message += ' - ' + e.description;
}

// Classify: permanent errors are not retried, transient ones are
const haystack = (message + ' ' + JSON.stringify(raw.error ?? '')).toLowerCase();
const httpCode = Number((haystack.match(/\b([45]\d\d)\b/) || [])[1]) || null;
const permanent = message.startsWith('PERMANENT:') || [400, 404, 413, 415, 422].includes(httpCode);
const outOfAttempts = ctx.attempts >= cfg.maxAttempts;
const status = (permanent || outOfAttempts) ? 'failed_permanent' : 'failed';

message = message.replace(/^PERMANENT:\s*/, '').slice(0, 500);
const executionUrl = cfg.n8nBaseUrl
  ? `${cfg.n8nBaseUrl.replace(/\/$/, '')}/workflow/${$workflow.id}/executions/${$execution.id}`
  : '';

return [{ json: {
  fileId: ctx.fileId, fileName: ctx.fileName, stage, status, httpCode,
  attempts: ctx.attempts, maxAttempts: cfg.maxAttempts,
  errorType: permanent ? 'permanent' : 'transient',
  message, executionUrl,
} }];

