*File:* {{ $json.fileName }}
*Stage:* {{ $json.stage }}
*Attempt:* {{ $json.attempts }}/{{ $json.maxAttempts }} · {{ $json.errorType }}{{ $json.httpCode ? ' · HTTP ' + $json.httpCode : '' }}
*Error:* {{ $json.message }}
{{ $json.status === 'failed' ? ':repeat: Will be retried automatically.' : ':no_entry: Will NOT be retried - needs manual action.' }}{{ $json.executionUrl ? '\n<' + $json.executionUrl + '|Open execution>' : '' }}
